/** Cross-boundary type definitions shared between main, preload, and renderer. */

export type DocumentStatus = 'imported' | 'indexing' | 'indexed' | 'error';

export interface Document {
  id: string;
  title: string;
  filename: string;
  /** Name of the stored copy inside the app data directory. */
  storedFilename: string;
  importedAt: string;
  size: number;
  status: DocumentStatus;
  chunks?: number;
  error?: string;
}

export interface Chunk {
  id: string;
  documentId: string;
  content: string;
  index: number;
  metadata: Record<string, string>;
}

export interface Citation {
  /** 1-based marker used in the answer text, e.g. [1]. */
  marker: number;
  documentId: string;
  documentTitle: string;
  chunkIndex: number;
  excerpt: string;
  score: number;
}

export interface QAResponse {
  answer: string;
  citations: Citation[];
  /** 0..1 — how well the retrieved passages cover the question. */
  confidence: number;
  /** Whether the answer came from the local extractive engine or an LLM. */
  engine: 'extractive' | 'llm';
  timestamp: string;
}

export interface QAHistory {
  question: string;
  response: QAResponse;
}

export interface AppStatus {
  documentsLoaded: number;
  documentsIndexed: number;
  indexStatus: 'idle' | 'indexing' | 'ready' | 'error';
  lastActivity: string;
  answerEngine: 'extractive' | 'llm';
}

export interface ImportResult {
  imported: Document[];
  failed: Array<{ filename: string; error: string }>;
}

export const SUPPORTED_EXTENSIONS = ['.txt', '.md', '.markdown'] as const;

/** IPC channel names -- single source of truth. */
export const IPC_CHANNELS = {
  // Document operations
  LIST_DOCUMENTS: 'documents:list',
  IMPORT_DIALOG: 'documents:import-dialog',
  IMPORT_PATHS: 'documents:import-paths',
  IMPORT_SAMPLES: 'documents:import-samples',
  GET_DOCUMENT: 'documents:get',
  GET_CONTENT: 'documents:content',
  DELETE_DOCUMENT: 'documents:delete',

  // Indexing
  START_INDEXING: 'indexing:start',
  GET_CHUNKS: 'indexing:chunks',

  // Q&A
  ASK_QUESTION: 'qa:ask',
  GET_HISTORY: 'qa:history',
  CLEAR_HISTORY: 'qa:clear-history',

  // App status
  GET_STATUS: 'app:status',
} as const;

export interface KnowledgeBaseApi {
  documents: {
    list: () => Promise<Document[]>;
    importDialog: () => Promise<ImportResult>;
    importFiles: (files: File[]) => Promise<ImportResult>;
    importSamples: () => Promise<ImportResult>;
    get: (id: string) => Promise<Document | null>;
    content: (id: string) => Promise<string | null>;
    delete: (id: string) => Promise<boolean>;
  };
  indexing: {
    start: (documentId?: string) => Promise<AppStatus>;
    chunks: (documentId: string) => Promise<Chunk[]>;
  };
  qa: {
    ask: (question: string) => Promise<QAResponse>;
    history: () => Promise<QAHistory[]>;
    clearHistory: () => Promise<void>;
  };
  status: () => Promise<AppStatus>;
}

