import * as fs from 'fs';
import * as path from 'path';

/**
 * Filesystem access rooted at a single data directory. Every relative path is
 * resolved and checked so callers can never read or write outside of it.
 */
export class PersistenceService {
  private dataDir: string;
  private documentsDir: string;

  constructor(dataDir: string) {
    this.dataDir = path.resolve(dataDir);
    this.documentsDir = path.join(this.dataDir, 'documents');
    fs.mkdirSync(this.documentsDir, { recursive: true });
  }

  private resolve(relativePath: string): string {
    const full = path.resolve(this.dataDir, relativePath);
    if (full !== this.dataDir && !full.startsWith(this.dataDir + path.sep)) {
      throw new Error(`Path escapes data directory: ${relativePath}`);
    }
    return full;
  }

  private writeAtomic(fullPath: string, content: string): void {
    fs.mkdirSync(path.dirname(fullPath), { recursive: true });
    const tmp = `${fullPath}.${process.pid}.${Date.now()}.tmp`;
    fs.writeFileSync(tmp, content, 'utf-8');
    fs.renameSync(tmp, fullPath);
  }

  /** Read a JSON file, returning null if it doesn't exist or is unreadable. */
  readJson<T>(relativePath: string): T | null {
    const fullPath = this.resolve(relativePath);
    if (!fs.existsSync(fullPath)) return null;
    try {
      return JSON.parse(fs.readFileSync(fullPath, 'utf-8')) as T;
    } catch (err) {
      console.error(`[persistence] Corrupt JSON at ${relativePath}:`, err);
      return null;
    }
  }

  /** Write a JSON file atomically (temp file + rename). */
  writeJson<T>(relativePath: string, data: T): void {
    this.writeAtomic(this.resolve(relativePath), JSON.stringify(data, null, 2));
  }

  readText(relativePath: string): string | null {
    const fullPath = this.resolve(relativePath);
    if (!fs.existsSync(fullPath)) return null;
    return fs.readFileSync(fullPath, 'utf-8');
  }

  writeText(relativePath: string, content: string): void {
    this.writeAtomic(this.resolve(relativePath), content);
  }

  delete(relativePath: string): void {
    const fullPath = this.resolve(relativePath);
    if (fs.existsSync(fullPath)) fs.unlinkSync(fullPath);
  }

  exists(relativePath: string): boolean {
    return fs.existsSync(this.resolve(relativePath));
  }

  /** Copy a file into the documents directory under the given stored name. */
  copyFileToDocuments(sourcePath: string, storedFilename: string): string {
    const destPath = this.resolve(path.join('documents', storedFilename));
    fs.copyFileSync(sourcePath, destPath);
    return destPath;
  }

  deleteFromDocuments(storedFilename: string): void {
    this.delete(path.join('documents', storedFilename));
  }

  getDataDir(): string {
    return this.dataDir;
  }
}

