import * as fs from 'fs';
import * as path from 'path';
import { v4 as uuidv4 } from 'uuid';
import { Document, SUPPORTED_EXTENSIONS } from '../shared/types';
import { PersistenceService } from './persistence-service';

export const DOCUMENTS_META = 'documents-meta.json';
export const MAX_DOCUMENT_BYTES = 5 * 1024 * 1024;

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

export function isValidId(id: unknown): id is string {
  return typeof id === 'string' && UUID_RE.test(id);
}

export function contentPath(id: string): string {
  if (!isValidId(id)) throw new Error(`Invalid document id: ${String(id)}`);
  return `content/${id}.txt`;
}

/** Normalise text for storage: strip BOM, unify line endings. */
export function normalizeText(raw: string): string {
  return raw.replace(/^﻿/, '').replace(/\r\n?/g, '\n');
}

export class DocumentService {
  constructor(private persistence: PersistenceService) {}

  listDocuments(): Document[] {
    return this.persistence.readJson<Document[]>(DOCUMENTS_META) ?? [];
  }

  /** Import a plain-text or Markdown file from disk. Throws with a user-readable message on failure. */
  importDocument(filePath: string): Document {
    const filename = path.basename(filePath);
    const ext = path.extname(filename).toLowerCase();
    if (!(SUPPORTED_EXTENSIONS as readonly string[]).includes(ext)) {
      throw new Error(`Unsupported file type "${ext || 'none'}". Supported: ${SUPPORTED_EXTENSIONS.join(', ')}`);
    }
    if (!fs.existsSync(filePath)) throw new Error('File not found');

    const stats = fs.statSync(filePath);
    if (!stats.isFile()) throw new Error('Not a regular file');
    if (stats.size > MAX_DOCUMENT_BYTES) {
      throw new Error(`File is larger than ${MAX_DOCUMENT_BYTES / 1024 / 1024} MB`);
    }

    const buffer = fs.readFileSync(filePath);
    if (buffer.includes(0)) throw new Error('File appears to be binary, not text');
    const content = normalizeText(buffer.toString('utf-8'));
    if (!content.trim()) throw new Error('File is empty');

    const id = uuidv4();
    const doc: Document = {
      id,
      title: deriveTitle(filename, content, ext),
      filename,
      storedFilename: `${id}${ext}`,
      importedAt: new Date().toISOString(),
      size: stats.size,
      status: 'imported',
    };

    this.persistence.copyFileToDocuments(filePath, doc.storedFilename);
    this.persistence.writeText(contentPath(id), content);

    const docs = this.listDocuments();
    docs.push(doc);
    this.persistence.writeJson(DOCUMENTS_META, docs);
    return doc;
  }

  getDocument(id: string): Document | null {
    return this.listDocuments().find(d => d.id === id) ?? null;
  }

  getDocumentContent(id: string): string | null {
    if (!isValidId(id)) return null;
    return this.persistence.readText(contentPath(id));
  }

  updateDocument(id: string, updates: Partial<Document>): Document | null {
    const docs = this.listDocuments();
    const index = docs.findIndex(d => d.id === id);
    if (index === -1) return null;
    docs[index] = { ...docs[index], ...updates, id };
    this.persistence.writeJson(DOCUMENTS_META, docs);
    return docs[index];
  }

  /** Delete a document's metadata, stored copy, and extracted text. Index cleanup is the caller's job. */
  deleteDocument(id: string): boolean {
    const docs = this.listDocuments();
    const doc = docs.find(d => d.id === id);
    if (!doc) return false;

    this.persistence.deleteFromDocuments(doc.storedFilename);
    this.persistence.delete(contentPath(id));
    this.persistence.writeJson(DOCUMENTS_META, docs.filter(d => d.id !== id));
    return true;
  }
}

function deriveTitle(filename: string, content: string, ext: string): string {
  if (ext !== '.txt') {
    const heading = content.match(/^#\s+(.+)$/m);
    if (heading) return heading[1].trim();
  }
  return filename.replace(/\.[^.]+$/, '');
}

