import { v4 as uuidv4 } from 'uuid';
import { Chunk } from '../shared/types';
import { PersistenceService } from './persistence-service';
import { DocumentService, isValidId } from './document-service';

const INDEX_META = 'index-meta.json';
const CHUNKS_DIR = 'chunks';

export const CHUNK_SIZE = 500;
/** Paragraphs longer than this are split at sentence boundaries. */
const MAX_PARAGRAPH = 800;

function chunksPath(documentId: string): string {
  if (!isValidId(documentId)) throw new Error(`Invalid document id: ${documentId}`);
  return `${CHUNKS_DIR}/${documentId}.json`;
}

export class IndexingService {
  private cache: Chunk[] | null = null;

  constructor(
    private persistence: PersistenceService,
    private documents: DocumentService,
  ) {}

  private readIndexMeta(): Record<string, string[]> {
    return this.persistence.readJson<Record<string, string[]>>(INDEX_META) ?? {};
  }

  isIndexed(documentId: string): boolean {
    return documentId in this.readIndexMeta();
  }

  /** Index (or re-index) a single document. Returns the number of chunks. */
  indexDocument(documentId: string): number {
    const content = this.documents.getDocumentContent(documentId);
    if (content === null) {
      this.documents.updateDocument(documentId, { status: 'error', error: 'Document content is missing' });
      throw new Error('Document content is missing');
    }

    this.documents.updateDocument(documentId, { status: 'indexing', error: undefined });
    try {
      const chunks = chunkText(content).map((text, index) => createChunk(documentId, index, text));
      this.persistence.writeJson(chunksPath(documentId), chunks);

      const meta = this.readIndexMeta();
      meta[documentId] = chunks.map(c => c.id);
      this.persistence.writeJson(INDEX_META, meta);

      this.documents.updateDocument(documentId, { status: 'indexed', chunks: chunks.length });
      this.cache = null;
      return chunks.length;
    } catch (err) {
      const message = err instanceof Error ? err.message : String(err);
      this.documents.updateDocument(documentId, { status: 'error', error: message });
      throw err;
    }
  }

  /** Index every document that isn't indexed yet. Failures are recorded on the document, not thrown. */
  indexPending(): void {
    const meta = this.readIndexMeta();
    for (const doc of this.documents.listDocuments()) {
      if (meta[doc.id] && doc.status === 'indexed') continue;
      try {
        this.indexDocument(doc.id);
      } catch (err) {
        console.error(`[indexing] Failed to index ${doc.filename}:`, err);
      }
    }
  }

  removeDocument(documentId: string): void {
    const meta = this.readIndexMeta();
    if (documentId in meta) {
      delete meta[documentId];
      this.persistence.writeJson(INDEX_META, meta);
    }
    this.persistence.delete(chunksPath(documentId));
    this.cache = null;
  }

  getChunksForDocument(documentId: string): Chunk[] {
    if (!isValidId(documentId)) return [];
    return this.persistence.readJson<Chunk[]>(chunksPath(documentId)) ?? [];
  }

  /** All chunks across indexed documents (cached until the index changes). */
  getAllChunks(): Chunk[] {
    if (this.cache) return this.cache;
    const all: Chunk[] = [];
    for (const docId of Object.keys(this.readIndexMeta())) {
      all.push(...this.getChunksForDocument(docId));
    }
    this.cache = all;
    return all;
  }
}

/** Split text into ~CHUNK_SIZE pieces at paragraph boundaries, splitting oversized paragraphs by sentence. */
export function chunkText(content: string, size = CHUNK_SIZE): string[] {
  const paragraphs = content
    .split(/\n\s*\n/)
    .map(p => p.trim())
    .filter(p => p.length > 0)
    .flatMap(p => (p.length > MAX_PARAGRAPH ? splitLongParagraph(p, size) : [p]));

  const chunks: string[] = [];
  let buffer = '';
  for (const para of paragraphs) {
    if (buffer && buffer.length + para.length + 2 > size) {
      chunks.push(buffer);
      buffer = para;
    } else {
      buffer = buffer ? `${buffer}\n\n${para}` : para;
    }
  }
  if (buffer) chunks.push(buffer);
  return chunks;
}

function splitLongParagraph(paragraph: string, size: number): string[] {
  const sentences = paragraph.match(/[^.!?]+(?:[.!?]+|$)\s*/g) ?? [paragraph];
  const parts: string[] = [];
  let buffer = '';
  for (const sentence of sentences) {
    if (buffer && buffer.length + sentence.length > size) {
      parts.push(buffer.trim());
      buffer = '';
    }
    buffer += sentence;
    // A single run-on "sentence" with no punctuation: hard-split it.
    while (buffer.length > size * 2) {
      parts.push(buffer.slice(0, size).trim());
      buffer = buffer.slice(size);
    }
  }
  if (buffer.trim()) parts.push(buffer.trim());
  return parts;
}

function createChunk(documentId: string, index: number, content: string): Chunk {
  return {
    id: uuidv4(),
    documentId,
    content,
    index,
    metadata: {
      charCount: String(content.length),
      wordCount: String(content.split(/\s+/).filter(Boolean).length),
    },
  };
}

