import { QAResponse, QAHistory, Citation, Chunk } from '../shared/types';
import { PersistenceService } from './persistence-service';
import { IndexingService } from './indexing-service';
import { DocumentService } from './document-service';
import { Bm25Index, ScoredChunk, tokenize } from './retrieval';

const QA_HISTORY_FILE = 'qa-history.json';
const MAX_HISTORY = 200;
const MAX_CITATIONS = 3;
const MAX_ANSWER_SENTENCES = 3;
/** Chunks scoring below this fraction of the best chunk are dropped. */
const RELATIVE_SCORE_CUTOFF = 0.35;

export interface LlmConfig {
  apiKey: string;
  model: string;
}

export const NO_DOCUMENTS_ANSWER =
  'No documents have been indexed yet. Import some documents first, then ask again.';
export const NOT_FOUND_ANSWER =
  "I couldn't find anything about that in your documents. Try different keywords, or import a document that covers it.";
export const EMPTY_QUERY_ANSWER =
  'Your question has no searchable keywords. Try asking with more specific terms.';

export class QaService {
  private index: Bm25Index | null = null;
  private indexedChunks: Chunk[] | null = null;

  constructor(
    private persistence: PersistenceService,
    private indexingService: IndexingService,
    private documents: DocumentService,
    private llm: LlmConfig | null = null,
  ) {}

  get engine(): 'extractive' | 'llm' {
    return this.llm ? 'llm' : 'extractive';
  }

  private getIndex(): Bm25Index {
    const chunks = this.indexingService.getAllChunks();
    if (!this.index || chunks !== this.indexedChunks) {
      this.index = new Bm25Index(chunks);
      this.indexedChunks = chunks;
    }
    return this.index;
  }

  async ask(rawQuestion: string): Promise<QAResponse> {
    const question = String(rawQuestion ?? '').trim().slice(0, 2000);
    if (!question) throw new Error('Question is empty');

    const response = await this.answer(question);
    this.saveToHistory(question, response);
    return response;
  }

  private async answer(question: string): Promise<QAResponse> {
    const index = this.getIndex();
    const base = { timestamp: new Date().toISOString() };

    if (index.size === 0) {
      return { ...base, answer: NO_DOCUMENTS_ANSWER, citations: [], confidence: 0, engine: 'extractive' };
    }
    const queryTerms = [...new Set(tokenize(question))];
    if (queryTerms.length === 0) {
      return { ...base, answer: EMPTY_QUERY_ANSWER, citations: [], confidence: 0, engine: 'extractive' };
    }

    const hits = index.search(question, 8);
    const top = hits.length ? hits.filter(h => h.score >= hits[0].score * RELATIVE_SCORE_CUTOFF) : [];
    if (top.length === 0) {
      return { ...base, answer: NOT_FOUND_ANSWER, citations: [], confidence: 0, engine: 'extractive' };
    }

    if (this.llm) {
      try {
        return { ...base, ...(await this.answerWithLlm(question, top.slice(0, 5))) };
      } catch (err) {
        console.error('[qa] LLM request failed, falling back to extractive answer:', err);
      }
    }
    return { ...base, ...this.answerExtractively(queryTerms, top, index) };
  }

  /** Build an answer from the best-matching sentences of the retrieved chunks. */
  private answerExtractively(
    queryTerms: string[],
    hits: ScoredChunk[],
    index: Bm25Index,
  ): Omit<QAResponse, 'timestamp'> {
    const totalWeight = queryTerms.reduce((s, t) => s + index.idf(t), 0) || 1;

    type Candidate = { text: string; hit: ScoredChunk; score: number; terms: Set<string> };
    const candidates: Candidate[] = [];
