import { Chunk } from '../shared/types';

const STOP_WORDS = new Set(
  `a about above after again against all am an and any are as at be because been before being below between both but by
  can could did do does doing down during each few for from further had has have having he her here hers herself him
  himself his how i if in into is it its itself just me more most my myself no nor not now of off on once only or other
  our ours ourselves out over own same she should so some such than that the their theirs them themselves then there
  these they this those through to too under until up very was we were what when where which while who whom why will
  with would you your yours yourself yourselves tell explain describe say says said please know give get also use used
  using us one may might must shall`.split(/\s+/),
);

/** Very light suffix stripping so "chunks"/"chunking"/"chunked" match "chunk". */
export function stem(word: string): string {
  if (word.length > 5 && word.endsWith('ies')) return word.slice(0, -3) + 'y';
  if (word.length > 5 && word.endsWith('ing')) return word.slice(0, -3);
  if (word.length > 4 && word.endsWith('ed')) return word.slice(0, -2);
  if (word.length > 4 && word.endsWith('es') && /(sh|ch|x|ss)es$/.test(word)) return word.slice(0, -2);
  if (word.length > 3 && word.endsWith('s') && !word.endsWith('ss')) return word.slice(0, -1);
  return word;
}

export function tokenize(text: string): string[] {
  const words = text.toLowerCase().match(/[\p{L}\p{N}]+/gu) ?? [];
  return words.filter(w => w.length > 1 && !STOP_WORDS.has(w)).map(stem);
}

export interface ScoredChunk {
  chunk: Chunk;
  score: number;
  matchedTerms: Set<string>;
}

/** BM25 index over chunks. Rebuild it whenever the chunk set changes. */
export class Bm25Index {
  private docs: Array<{ chunk: Chunk; tf: Map<string, number>; length: number }>;
  private df = new Map<string, number>();
  private avgLength: number;

  constructor(chunks: Chunk[], private k1 = 1.5, private b = 0.75) {
    this.docs = chunks.map(chunk => {
      const tokens = tokenize(chunk.content);
      const tf = new Map<string, number>();
      for (const t of tokens) tf.set(t, (tf.get(t) ?? 0) + 1);
      for (const t of tf.keys()) this.df.set(t, (this.df.get(t) ?? 0) + 1);
      return { chunk, tf, length: tokens.length };
    });
    this.avgLength = this.docs.reduce((s, d) => s + d.length, 0) / Math.max(1, this.docs.length);
  }

  get size(): number {
    return this.docs.length;
  }

  idf(term: string): number {
    const n = this.docs.length;
    const df = this.df.get(term) ?? 0;
    return Math.log(1 + (n - df + 0.5) / (df + 0.5));
  }

  search(query: string, limit = 5): ScoredChunk[] {
    const terms = [...new Set(tokenize(query))];
    if (terms.length === 0) return [];

    const results: ScoredChunk[] = [];
    for (const doc of this.docs) {
      let score = 0;
      const matched = new Set<string>();
      for (const term of terms) {
        const f = doc.tf.get(term);
        if (!f) continue;
        matched.add(term);
        const norm = f + this.k1 * (1 - this.b + (this.b * doc.length) / this.avgLength);
        score += this.idf(term) * ((f * (this.k1 + 1)) / norm);
      }
      if (score > 0) results.push({ chunk: doc.chunk, score, matchedTerms: matched });
    }
    return results.sort((a, b) => b.score - a.score).slice(0, limit);
  }
}

