    const sources = hits
      .map((hit, i) => `[${i + 1}] (${all[i].documentTitle}, passage ${hit.chunk.index + 1})\n${hit.chunk.content}`)
      .join('\n\n');

    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        'x-api-key': llm.apiKey,
        'anthropic-version': '2023-06-01',
      },
      signal: AbortSignal.timeout(60_000),
      body: JSON.stringify({
        model: llm.model,
        max_tokens: 1024,
        system:
          'You answer questions using only the numbered source passages provided. Cite every claim with its ' +
          'source marker like [1]. If the passages do not contain the answer, say so plainly and do not guess. ' +
          'Be concise.',
        messages: [{ role: 'user', content: `Sources:\n\n${sources}\n\nQuestion: ${question}` }],
      }),
    });
    if (!res.ok) throw new Error(`Anthropic API ${res.status}: ${(await res.text()).slice(0, 300)}`);

    const data = (await res.json()) as { content?: Array<{ type: string; text?: string }> };
    const answer = (data.content ?? []).filter(b => b.type === 'text').map(b => b.text).join('').trim();
    if (!answer) throw new Error('Empty response from model');

    const used = new Set([...answer.matchAll(/\[(\d+)\]/g)].map(m => Number(m[1])));
    const citations = all.filter(c => used.has(c.marker));
    return {
      answer,
      citations,
      confidence: citations.length > 0 ? 0.8 : 0.3,
      engine: 'llm',
    };
  }

  private toCitation(hit: ScoredChunk, marker: number): Citation {
    const doc = this.documents.getDocument(hit.chunk.documentId);
    return {
      marker,
      documentId: hit.chunk.documentId,
      documentTitle: doc?.title ?? 'Unknown document',
      chunkIndex: hit.chunk.index,
      excerpt: hit.chunk.content.length > 240 ? `${hit.chunk.content.slice(0, 240).trimEnd()}…` : hit.chunk.content,
      score: round2(hit.score),
    };
  }

  getHistory(): QAHistory[] {
    return this.persistence.readJson<QAHistory[]>(QA_HISTORY_FILE) ?? [];
  }

  clearHistory(): void {
    this.persistence.writeJson(QA_HISTORY_FILE, []);
  }

  private saveToHistory(question: string, response: QAResponse): void {
    const history = this.getHistory();
    history.push({ question, response });
    this.persistence.writeJson(QA_HISTORY_FILE, history.slice(-MAX_HISTORY));
  }
}

/** Split a chunk into answer-sized units: sentences, list items, skipping Markdown headings. */
export function splitSentences(text: string): string[] {
  const out: string[] = [];
  for (const rawLine of text.split('\n')) {
    const line = rawLine.trim();
    if (!line || /^#{1,6}\s/.test(line)) continue;
    const cleaned = line
      .replace(/^([-*+]|\d+[.)])\s+/, '')
      .replace(/`([^`]*)`/g, '$1')
      .replace(/\*\*([^*]+)\*\*/g, '$1');
    const sentences = cleaned.match(/[^.!?]+(?:[.!?]+(?=\s|$)|$)/g) ?? [cleaned];
    for (const s of sentences) {
      const t = s.trim();
      if (t.split(/\s+/).length >= 3) out.push(t);
    }
  }
  return out;
}

function ensurePeriod(s: string): string {
  return /[.!?:]$/.test(s) ? s : `${s}.`;
}

function round2(n: number): number {
  return Math.round(n * 100) / 100;
}

