import { contextBridge, ipcRenderer, webUtils } from 'electron';
// Type-only import: sandboxed preloads cannot require local modules at runtime,
// so channel names are repeated here and checked against the shared definition at compile time.
import type { IPC_CHANNELS as SharedChannels, KnowledgeBaseApi } from '../shared/types';

const CH: typeof SharedChannels = {
  LIST_DOCUMENTS: 'documents:list',
  IMPORT_DIALOG: 'documents:import-dialog',
  IMPORT_PATHS: 'documents:import-paths',
  IMPORT_SAMPLES: 'documents:import-samples',
  GET_DOCUMENT: 'documents:get',
  GET_CONTENT: 'documents:content',
  DELETE_DOCUMENT: 'documents:delete',
  START_INDEXING: 'indexing:start',
  GET_CHUNKS: 'indexing:chunks',
  ASK_QUESTION: 'qa:ask',
  GET_HISTORY: 'qa:history',
  CLEAR_HISTORY: 'qa:clear-history',
  GET_STATUS: 'app:status',
};

const api: KnowledgeBaseApi = {
  documents: {
    list: () => ipcRenderer.invoke(CH.LIST_DOCUMENTS),
    importDialog: () => ipcRenderer.invoke(CH.IMPORT_DIALOG),
    // File.path was removed in Electron 32; resolve dropped files' paths here.
    importFiles: (files: File[]) =>
