import { BrowserWindow, IpcMain, dialog } from 'electron';
import * as fs from 'fs';
import * as path from 'path';
import { DocumentService, isValidId } from '../services/document-service';
import { IndexingService } from '../services/indexing-service';
import { QaService } from '../services/qa-service';
import { AppStatus, ImportResult, IPC_CHANNELS, SUPPORTED_EXTENSIONS } from '../shared/types';

export interface Services {
  documentService: DocumentService;
  indexingService: IndexingService;
  qaService: QaService;
  /** Directory of bundled sample documents, if any. */
  samplesDir: string | null;
}

function requireId(id: unknown): string {
  if (!isValidId(id)) throw new Error('Invalid document id');
  return id;
}

export function registerIpcHandlers(ipcMain: IpcMain, services: Services) {
  const { documentService, indexingService, qaService, samplesDir } = services;
  let lastActivity = new Date().toISOString();
  const touch = () => {
    lastActivity = new Date().toISOString();
  };

  const getStatus = (): AppStatus => {
    const docs = documentService.listDocuments();
    const indexed = docs.filter(d => d.status === 'indexed').length;
    const anyIndexing = docs.some(d => d.status === 'indexing');
    const anyError = docs.some(d => d.status === 'error');
    return {
      documentsLoaded: docs.length,
      documentsIndexed: indexed,
      indexStatus: anyIndexing ? 'indexing' : anyError ? 'error' : docs.length > 0 && indexed === docs.length ? 'ready' : 'idle',
      lastActivity,
      answerEngine: qaService.engine,
    };
  };

  /** Import files and index them right away so they are immediately searchable. */
  const importPaths = (paths: unknown): ImportResult => {
    if (!Array.isArray(paths)) throw new Error('Expected a list of file paths');
    const result: ImportResult = { imported: [], failed: [] };
    for (const p of paths) {
      if (typeof p !== 'string' || !p) continue;
      try {
        const doc = documentService.importDocument(p);
        try {
          indexingService.indexDocument(doc.id);
        } catch {
          // Status is recorded on the document; it still shows up in the list.
        }
        result.imported.push(documentService.getDocument(doc.id) ?? doc);
      } catch (err) {
        result.failed.push({ filename: path.basename(p), error: err instanceof Error ? err.message : String(err) });
      }
    }
    touch();
    return result;
  };

  ipcMain.handle(IPC_CHANNELS.LIST_DOCUMENTS, () => documentService.listDocuments());

  ipcMain.handle(IPC_CHANNELS.IMPORT_DIALOG, async event => {
    const win = BrowserWindow.fromWebContents(event.sender);
    const options: Electron.OpenDialogOptions = {
      title: 'Import documents',
      properties: ['openFile', 'multiSelections'],
      filters: [{ name: 'Text documents', extensions: SUPPORTED_EXTENSIONS.map(e => e.slice(1)) }],
    };
    const { canceled, filePaths } = win ? await dialog.showOpenDialog(win, options) : await dialog.showOpenDialog(options);
    if (canceled) return { imported: [], failed: [] } satisfies ImportResult;
    return importPaths(filePaths);
  });

  ipcMain.handle(IPC_CHANNELS.IMPORT_PATHS, (_event, paths: unknown) => importPaths(paths));

  ipcMain.handle(IPC_CHANNELS.IMPORT_SAMPLES, () => {
    if (!samplesDir || !fs.existsSync(samplesDir)) throw new Error('No sample documents are bundled with this build');
    const existing = new Set(documentService.listDocuments().map(d => d.filename));
    const files = fs
      .readdirSync(samplesDir)
      .filter(f => !existing.has(f))
      .map(f => path.join(samplesDir, f));
    return importPaths(files);
  });

  ipcMain.handle(IPC_CHANNELS.GET_DOCUMENT, (_event, id: unknown) => documentService.getDocument(requireId(id)));

  ipcMain.handle(IPC_CHANNELS.GET_CONTENT, (_event, id: unknown) => documentService.getDocumentContent(requireId(id)));

  ipcMain.handle(IPC_CHANNELS.DELETE_DOCUMENT, (_event, id: unknown) => {
    const docId = requireId(id);
    indexingService.removeDocument(docId);
    const deleted = documentService.deleteDocument(docId);
    touch();
    return deleted;
  });

  ipcMain.handle(IPC_CHANNELS.START_INDEXING, (_event, documentId?: unknown) => {
    if (documentId === undefined || documentId === null) {
      indexingService.indexPending();
    } else {
      indexingService.indexDocument(requireId(documentId));
    }
    touch();
    return getStatus();
  });

  ipcMain.handle(IPC_CHANNELS.GET_CHUNKS, (_event, id: unknown) => indexingService.getChunksForDocument(requireId(id)));

  ipcMain.handle(IPC_CHANNELS.ASK_QUESTION, async (_event, question: unknown) => {
    if (typeof question !== 'string') throw new Error('Question must be text');
    const response = await qaService.ask(question);
    touch();
    return response;
  });

  ipcMain.handle(IPC_CHANNELS.GET_HISTORY, () => qaService.getHistory());

  ipcMain.handle(IPC_CHANNELS.CLEAR_HISTORY, () => qaService.clearHistory());

  ipcMain.handle(IPC_CHANNELS.GET_STATUS, () => getStatus());
}

