import { app, BrowserWindow, ipcMain, shell } from 'electron';
import * as path from 'path';
import { registerIpcHandlers } from './ipc-handlers';
import { DocumentService } from '../services/document-service';
import { QaService } from '../services/qa-service';
import { IndexingService } from '../services/indexing-service';
import { PersistenceService } from '../services/persistence-service';

let mainWindow: BrowserWindow | null = null;

function createWindow() {
  mainWindow = new BrowserWindow({
    width: 1280,
    height: 820,
    minWidth: 900,
    minHeight: 600,
    backgroundColor: '#14161c',
    title: 'Knowledge Base',
    webPreferences: {
      preload: path.join(__dirname, '..', 'preload', 'preload.js'),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
    },
  });

  mainWindow.loadFile(path.join(__dirname, '..', 'renderer', 'index.html'));

  // Never navigate the app window away from the bundled UI; open web links in the browser instead.
  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    if (/^https?:\/\//.test(url)) shell.openExternal(url);
    return { action: 'deny' };
  });
  mainWindow.webContents.on('will-navigate', event => event.preventDefault());

  mainWindow.on('closed', () => {
    mainWindow = null;
  });
}

function initializeServices() {
  const dataDir = path.join(app.getPath('userData'), 'knowledge-base-data');
  const persistence = new PersistenceService(dataDir);
  const documentService = new DocumentService(persistence);
  const indexingService = new IndexingService(persistence, documentService);

  // Optional: set ANTHROPIC_API_KEY to have Claude write answers from the retrieved passages.
  // Without it, answers are extracted locally and no document text leaves the machine.
  const apiKey = process.env.ANTHROPIC_API_KEY?.trim();
  const llm = apiKey ? { apiKey, model: process.env.KB_MODEL?.trim() || 'claude-opus-5-5' } : null;
  const qaService = new QaService(persistence, indexingService, documentService, llm);

  // Recover from a crash mid-index and pick up anything not yet indexed.
  indexingService.indexPending();

  registerIpcHandlers(ipcMain, {
    documentService,
    indexingService,
    qaService,
    samplesDir: path.join(app.getAppPath(), 'data', 'sample-documents'),
  });
  console.log(`[main] Data directory: ${dataDir}; answer engine: ${qaService.engine}`);
}

app.whenReady().then(() => {
  initializeServices();
  createWindow();

  app.on('activate', () => {
    if (BrowserWindow.getAllWindows().length === 0) createWindow();
  });
});

app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') app.quit();
});

