import { useCallback, useEffect, useRef, useState } from 'react';
import { DocumentList } from './components/DocumentList';
import { DocumentViewer } from './components/DocumentViewer';
import { QaPanel } from './components/QaPanel';
import { StatusBar } from './components/StatusBar';
import type { AppStatus, Citation, Document, ImportResult, QAHistory } from '@shared/types';

export interface Highlight {
  documentId: string;
  chunkIndex: number;
  /** Changes on every click so re-selecting the same citation re-scrolls. */
  nonce: number;
}

interface Toast {
  id: number;
  message: string;
  kind: 'info' | 'error';
}

/** Electron wraps errors thrown in main as "Error invoking remote method 'x': Error: msg". */
export function errorMessage(err: unknown): string {
  const raw = err instanceof Error ? err.message : String(err);
  return raw.replace(/^Error invoking remote method '[^']+': (Error: )?/, '');
}

const kb = () => window.knowledgeBase;

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [highlight, setHighlight] = useState<Highlight | null>(null);
  const [status, setStatus] = useState<AppStatus | null>(null);
  const [history, setHistory] = useState<QAHistory[]>([]);
  const [pendingQuestion, setPendingQuestion] = useState<string | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [busy, setBusy] = useState(false);
  const toastId = useRef(0);

  const notify = useCallback((message: string, kind: Toast['kind'] = 'info') => {
    const id = ++toastId.current;
    setToasts(t => [...t, { id, message, kind }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), kind === 'error' ? 8000 : 4000);
  }, []);

  const refresh = useCallback(async () => {
    try {
      const [docs, st] = await Promise.all([kb().documents.list(), kb().status()]);
      setDocuments(docs);
      setStatus(st);
