import { useState } from 'react';
import type { Document } from '@shared/types';

interface Props {
  documents: Document[];
  selectedId: string | null;
  busy: boolean;
  onSelect: (doc: Document) => void;
  onImport: () => void;
  onDropFiles: (files: File[]) => void;
  onImportSamples: () => void;
}

export function formatSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
}

const STATUS_LABEL: Record<Document['status'], string> = {
  imported: 'Not indexed',
  indexing: 'Indexing…',
  indexed: 'Indexed',
  error: 'Index error',
};

export function DocumentList({ documents, selectedId, busy, onSelect, onImport, onDropFiles, onImportSamples }: Props) {
  const [dragging, setDragging] = useState(false);

  return (
    <aside
      className="sidebar"
      onDragOver={e => {
        if (e.dataTransfer.types.includes('Files')) {
          e.preventDefault();
          setDragging(true);
        }
      }}
      onDragLeave={e => {
        if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setDragging(false);
      }}
      onDrop={e => {
        e.preventDefault();
        setDragging(false);
        const files = Array.from(e.dataTransfer.files);
        if (files.length) onDropFiles(files);
      }}
    >
      <div className="sidebar-header">
        <h1>Documents{documents.length > 0 && ` (${documents.length})`}</h1>
        <button className="btn primary small" onClick={onImport} disabled={busy}>
          {busy ? 'Importing…' : '+ Import'}
        </button>
      </div>

      {documents.length === 0 ? (
        <div className="empty">
          <p>No documents yet.</p>
          <p>Import .txt or .md files, or drag them here.</p>
          <p>
            <button className="btn link" onClick={onImportSamples} disabled={busy}>
              Load sample documents
            </button>
          </p>
        </div>
      ) : (
        <ul className="doc-list">
          {documents.map(doc => (
            <li key={doc.id}>
              <button
                className={`doc-item${doc.id === selectedId ? ' selected' : ''}`}
                onClick={() => onSelect(doc)}
                title={doc.filename}
              >
                <span className={`dot ${doc.status}`} title={STATUS_LABEL[doc.status]} />
                <span className="info">
                  <div className="title">{doc.title}</div>
                  <div className="meta">
                    {doc.filename} · {formatSize(doc.size)}
                  </div>
                </span>
              </button>
            </li>
          ))}
        </ul>
      )}
      {dragging && <div className="drop-overlay">Drop to import</div>}
    </aside>
  );
}

export { STATUS_LABEL };

