import { useCallback, useEffect, useRef, useState } from 'react';
import { DocumentList } from './components/DocumentList';
import { DocumentViewer } from './components/DocumentViewer';
import { QaPanel } from './components/QaPanel';
import { StatusBar } from './components/StatusBar';
import type { AppStatus, Citation, Document, ImportResult, QAHistory } from '@shared/types';

export interface Highlight {
  documentId: string;
  chunkIndex: number;
  /** Changes on every click so re-selecting the same citation re-scrolls. */
  nonce: number;
}

interface Toast {
  id: number;
  message: string;
  kind: 'info' | 'error';
}

/** Electron wraps errors thrown in main as "Error invoking remote method 'x': Error: msg". */
export function errorMessage(err: unknown): string {
  const raw = err instanceof Error ? err.message : String(err);
  return raw.replace(/^Error invoking remote method '[^']+': (Error: )?/, '');
}

const kb = () => window.knowledgeBase;

export function App() {
  const [documents, setDocuments] = useState<Document[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [highlight, setHighlight] = useState<Highlight | null>(null);
  const [status, setStatus] = useState<AppStatus | null>(null);
  const [history, setHistory] = useState<QAHistory[]>([]);
  const [pendingQuestion, setPendingQuestion] = useState<string | null>(null);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [busy, setBusy] = useState(false);
  const toastId = useRef(0);

  const notify = useCallback((message: string, kind: Toast['kind'] = 'info') => {
    const id = ++toastId.current;
    setToasts(t => [...t, { id, message, kind }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), kind === 'error' ? 8000 : 4000);
  }, []);

  const refresh = useCallback(async () => {
    try {
      const [docs, st] = await Promise.all([kb().documents.list(), kb().status()]);
      setDocuments(docs);
      setStatus(st);
      setSelectedId(id => (id && docs.some(d => d.id === id) ? id : null));
    } catch (err) {
      notify(`Couldn't load documents: ${errorMessage(err)}`, 'error');
    }
  }, [notify]);

  useEffect(() => {
    refresh();
    kb().qa.history().then(setHistory).catch(() => undefined);
  }, [refresh]);

  const runImport = useCallback(
    async (fn: () => Promise<ImportResult>) => {
      setBusy(true);
      try {
        const result = await fn();
        await refresh();
        if (result.imported.length > 0) {
          setSelectedId(result.imported[result.imported.length - 1].id);
          setHighlight(null);
          notify(`Imported ${result.imported.length} document${result.imported.length === 1 ? '' : 's'}`);
        }
        for (const f of result.failed) notify(`${f.filename}: ${f.error}`, 'error');
      } catch (err) {
        notify(`Import failed: ${errorMessage(err)}`, 'error');
      } finally {
        setBusy(false);
      }
    },
    [refresh, notify],
  );

  const handleDelete = useCallback(
    async (doc: Document) => {
      try {
        await kb().documents.delete(doc.id);
        if (selectedId === doc.id) setSelectedId(null);
        await refresh();
        notify(`Deleted "${doc.title}"`);
      } catch (err) {
        notify(`Delete failed: ${errorMessage(err)}`, 'error');
      }
    },
    [selectedId, refresh, notify],
  );

  const handleReindex = useCallback(
    async (doc: Document) => {
      try {
        await kb().indexing.start(doc.id);
      } catch (err) {
        notify(`Indexing failed: ${errorMessage(err)}`, 'error');
      }
      await refresh();
    },
    [refresh, notify],
  );

  const handleAsk = useCallback(
    async (question: string) => {
      setPendingQuestion(question);
      try {
        const response = await kb().qa.ask(question);
        setHistory(h => [...h, { question, response }]);
        const first = response.citations[0];
        if (first) setHighlight({ documentId: first.documentId, chunkIndex: first.chunkIndex, nonce: Date.now() });
        if (first) setSelectedId(first.documentId);
        kb().status().then(setStatus).catch(() => undefined);
      } catch (err) {
        notify(`Couldn't answer: ${errorMessage(err)}`, 'error');
      } finally {
        setPendingQuestion(null);
      }
    },
    [notify],
  );

  const handleClearHistory = useCallback(async () => {
    await kb().qa.clearHistory();
    setHistory([]);
  }, []);

  const openCitation = useCallback((c: Citation) => {
    setSelectedId(c.documentId);
    setHighlight({ documentId: c.documentId, chunkIndex: c.chunkIndex, nonce: Date.now() });
  }, []);

  // Prevent the window from navigating to a file that's dropped outside the drop zone.
  useEffect(() => {
    const stop = (e: DragEvent) => e.preventDefault();
    window.addEventListener('dragover', stop);
    window.addEventListener('drop', stop);
    return () => {
      window.removeEventListener('dragover', stop);
      window.removeEventListener('drop', stop);
    };
  }, []);

  const selected = documents.find(d => d.id === selectedId) ?? null;

  return (
    <div className="app">
      <div className="columns">
        <DocumentList
          documents={documents}
          selectedId={selectedId}
          busy={busy}
          onSelect={doc => {
            setSelectedId(doc.id);
            setHighlight(null);
          }}
          onImport={() => runImport(() => kb().documents.importDialog())}
          onDropFiles={files => runImport(() => kb().documents.importFiles(files))}
          onImportSamples={() => runImport(() => kb().documents.importSamples())}
        />
        <DocumentViewer
          document={selected}
          highlight={highlight && highlight.documentId === selectedId ? highlight : null}
          onDelete={handleDelete}
          onReindex={handleReindex}
          hasDocuments={documents.length > 0}
        />
        <QaPanel
          history={history}
          pendingQuestion={pendingQuestion}
          canAsk={documents.some(d => d.status === 'indexed')}
          onAsk={handleAsk}
          onClear={handleClearHistory}
          onOpenCitation={openCitation}
        />
      </div>
      <StatusBar status={status} />
      <div className="toasts" role="status" aria-live="polite">
        {toasts.map(t => (
          <div key={t.id} className={`toast ${t.kind}`}>
            <span>{t.message}</span>
            <button aria-label="Dismiss" onClick={() => setToasts(ts => ts.filter(x => x.id !== t.id))}>
              ✕
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

