import { useEffect, useRef, useState } from 'react';
import type { Chunk, Document } from '@shared/types';
import type { Highlight } from '../App';
import { formatSize, STATUS_LABEL } from './DocumentList';

interface Props {
  document: Document | null;
  highlight: Highlight | null;
  hasDocuments: boolean;
  onDelete: (doc: Document) => void;
  onReindex: (doc: Document) => void;
}

export function DocumentViewer({ document, highlight, hasDocuments, onDelete, onReindex }: Props) {
  const [content, setContent] = useState<string | null>(null);
  const [chunks, setChunks] = useState<Chunk[]>([]);
  const [loadError, setLoadError] = useState<string | null>(null);
  const [showPassages, setShowPassages] = useState(false);
  const [confirmDelete, setConfirmDelete] = useState(false);
  const bodyRef = useRef<HTMLDivElement>(null);

  const docId = document?.id;
  const docStatus = document?.status;

  useEffect(() => {
    setConfirmDelete(false);
    if (!docId) return;
    let cancelled = false;
    setLoadError(null);
    Promise.all([window.knowledgeBase.documents.content(docId), window.knowledgeBase.indexing.chunks(docId)])
      .then(([text, ch]) => {
        if (cancelled) return;
        setContent(text);
        setChunks(ch);
        bodyRef.current?.scrollTo({ top: 0 });
      })
      .catch(err => !cancelled && setLoadError(String(err)));
    return () => {
      cancelled = true;
    };
  }, [docId, docStatus]);

  // Scroll the cited passage into view once it's rendered.
  useEffect(() => {
    if (!highlight || chunks.length === 0) return;
    const el = bodyRef.current?.querySelector(`[data-chunk="${highlight.chunkIndex}"]`);
    el?.scrollIntoView({ behavior: 'smooth', block: 'center' });
  }, [highlight, chunks]);

  if (!document) {
    return (
      <main className="viewer">
        <div className="placeholder">
          <h2>{hasDocuments ? 'Select a document' : 'Welcome'}</h2>
          <p>
            {hasDocuments
              ? 'Pick a document on the left to read it, or ask a question on the right.'
              : 'Import some documents to read them here and ask questions about them.'}
          </p>
        </div>
      </main>
    );
  }

  return (
    <main className="viewer">
      <header className="viewer-header">
        <h2>{document.title}</h2>
        <div className="meta">
          <span>{document.filename}</span>
          <span>{formatSize(document.size)}</span>
          <span>Imported {new Date(document.importedAt).toLocaleString()}</span>
          <span>
            <span className={`dot ${document.status}`} style={{ display: 'inline-block', marginRight: 5 }} />
            {STATUS_LABEL[document.status]}
            {document.status === 'indexed' && document.chunks !== undefined && ` · ${document.chunks} passages`}
          </span>
          <span style={{ flex: 1 }} />
          {chunks.length > 0 && (
            <button className="btn small" onClick={() => setShowPassages(s => !s)}>
              {showPassages ? 'Hide' : 'Show'} passages
            </button>
          )}
          <button className="btn small" onClick={() => onReindex(document)}>
            {document.status === 'indexed' ? 'Re-index' : 'Index'}
          </button>
          {confirmDelete ? (
            <>
              <button className="btn small danger" onClick={() => onDelete(document)}>
                Confirm delete
              </button>
              <button className="btn small" onClick={() => setConfirmDelete(false)}>
                Cancel
              </button>
            </>
          ) : (
            <button className="btn small danger" onClick={() => setConfirmDelete(true)}>
              Delete
            </button>
          )}
        </div>
        {document.error && <div className="error-text" style={{ fontSize: 12, marginTop: 4 }}>{document.error}</div>}
      </header>

      <div className="viewer-body" ref={bodyRef}>
        <article className={`doc-text${showPassages ? ' show-passages' : ''}`}>
          {loadError ? (
            <p className="error-text">Couldn't load this document: {loadError}</p>
          ) : chunks.length > 0 ? (
            chunks.map(chunk => (
              <div
                key={chunk.id}
                data-chunk={chunk.index}
                className={`passage${highlight?.chunkIndex === chunk.index ? ' highlight' : ''}`}
              >
                <div className="label">Passage {chunk.index + 1}</div>
                {chunk.content}
              </div>
            ))
          ) : (
            <div className="passage">{content ?? ''}</div>
          )}
        </article>
      </div>
    </main>
  );
}

import { Fragment, useEffect, useRef, useState } from 'react';
import type { Citation, QAHistory, QAResponse } from '@shared/types';

interface Props {
  history: QAHistory[];
  pendingQuestion: string | null;
  canAsk: boolean;
  onAsk: (question: string) => void;
  onClear: () => void;
  onOpenCitation: (citation: Citation) => void;
}

const SUGGESTIONS = [
  'What are the layers of the architecture?',
  'How are documents split into chunks?',
  'What did the team decide about the vector database?',
];

export function QaPanel({ history, pendingQuestion, canAsk, onAsk, onClear, onOpenCitation }: Props) {
  const [question, setQuestion] = useState('');
  const threadRef = useRef<HTMLDivElement>(null);
  const busy = pendingQuestion !== null;

  useEffect(() => {
    threadRef.current?.scrollTo({ top: threadRef.current.scrollHeight, behavior: 'smooth' });
  }, [history.length, pendingQuestion]);

  const submit = (text: string) => {
    const q = text.trim();
    if (!q || busy) return;
    onAsk(q);
    setQuestion('');
  };

  return (
    <section className="qa">
      <div className="qa-header">
        <h2>Ask your documents</h2>
        {history.length > 0 && (
          <button className="btn small" onClick={onClear} disabled={busy}>
            Clear
          </button>
        )}
      </div>

      <div className="qa-thread" ref={threadRef}>
        {history.length === 0 && !busy && (
          <div className="empty" style={{ padding: '12px 4px' }}>
            {canAsk ? (
              <>
                <p>Ask anything about your indexed documents. Answers cite the passages they come from.</p>
                <div className="suggestions">
                  {SUGGESTIONS.map(s => (
                    <button key={s} className="btn" onClick={() => submit(s)}>
                      {s}
                    </button>
                  ))}
                </div>
              </>
            ) : (
              <p>Import and index a document to start asking questions.</p>
            )}
          </div>
        )}

        {history.map((entry, i) => (
          <Fragment key={`${entry.response.timestamp}-${i}`}>
            <div className="question">{entry.question}</div>
            <Answer response={entry.response} onOpenCitation={onOpenCitation} />
          </Fragment>
        ))}

        {pendingQuestion && (
          <>
            <div className="question">{pendingQuestion}</div>
            <div className="answer thinking">Searching your documents…</div>
          </>
        )}
      </div>

      <form
        className="qa-form"
        onSubmit={e => {
          e.preventDefault();
          submit(question);
        }}
      >
        <textarea
          value={question}
          rows={2}
          maxLength={2000}
          placeholder={canAsk ? 'Ask a question… (Enter to send)' : 'No indexed documents yet'}
          onChange={e => setQuestion(e.target.value)}
          onKeyDown={e => {
            if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
              e.preventDefault();
              submit(question);
            }
          }}
        />
        <button type="submit" className="btn primary" disabled={busy || !question.trim()}>
          Ask
        </button>
      </form>
    </section>
  );
}

function Answer({ response, onOpenCitation }: { response: QAResponse; onOpenCitation: (c: Citation) => void }) {
  const byMarker = new Map(response.citations.map(c => [c.marker, c]));
  // Turn "[n]" markers into clickable chips that jump to the cited passage.
  const parts = response.answer.split(/(\[\d+\])/g).map((part, i) => {
    const m = part.match(/^\[(\d+)\]$/);
    const citation = m ? byMarker.get(Number(m[1])) : undefined;
    if (!citation) return <Fragment key={i}>{part}</Fragment>;
    return (
      <button
        key={i}
        className="marker"
        title={`${citation.documentTitle}, passage ${citation.chunkIndex + 1}`}
        onClick={() => onOpenCitation(citation)}
      >
        {citation.marker}
      </button>
    );
  });

  const level = response.confidence >= 0.7 ? 'high' : response.confidence >= 0.45 ? 'mid' : 'low';
  const label = response.citations.length === 0 ? 'no sources' : `${level} confidence`;

  return (
    <div className="answer">
      <div className="text">{parts}</div>
      {response.citations.length > 0 && (
        <div className="sources">
          {response.citations.map(c => (
            <button key={c.marker} className="source" onClick={() => onOpenCitation(c)}>
              <div className="src-title">
                [{c.marker}] {c.documentTitle} · passage {c.chunkIndex + 1}
              </div>
              <div className="src-excerpt">{c.excerpt}</div>
            </button>
          ))}
        </div>
      )}
      <div className="answer-meta">
        <span className={`badge ${response.citations.length === 0 ? 'low' : level}`}>{label}</span>
        <span>{response.engine === 'llm' ? 'Written by Claude from sources' : 'Extracted from sources'}</span>
      </div>
    </div>
  );
}

import type { AppStatus } from '@shared/types';

const LABEL: Record<AppStatus['indexStatus'], string> = {
  idle: 'Not indexed',
  indexing: 'Indexing…',
  ready: 'Index ready',
  error: 'Some documents failed to index',
};

export function StatusBar({ status }: { status: AppStatus | null }) {
  if (!status) return <footer className="statusbar">Loading…</footer>;
  return (
    <footer className="statusbar">
      <span>
        <span className={`dot ${status.indexStatus}`} />
        {LABEL[status.indexStatus]}
      </span>
      <span>
        {status.documentsIndexed}/{status.documentsLoaded} documents indexed
      </span>
      <span>Answers: {status.answerEngine === 'llm' ? 'Claude (from your documents)' : 'local extractive'}</span>
      {status.lastActivity && <span>Last activity {new Date(status.lastActivity).toLocaleTimeString()}</span>}
    </footer>
  );
}

