import { afterEach, beforeEach, describe, expect, it } from 'vitest';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { PersistenceService } from '../src/services/persistence-service';
import { DocumentService } from '../src/services/document-service';
import { IndexingService, chunkText } from '../src/services/indexing-service';
import { QaService, NOT_FOUND_ANSWER, NO_DOCUMENTS_ANSWER, splitSentences } from '../src/services/qa-service';
import { Bm25Index, stem, tokenize } from '../src/services/retrieval';

const SAMPLES = path.join(__dirname, '..', 'data', 'sample-documents');

let tmp: string;
let dataDir: string;
let persistence: PersistenceService;
let documents: DocumentService;
let indexing: IndexingService;
let qa: QaService;

function writeFile(name: string, content: string | Buffer): string {
  const p = path.join(tmp, 'src', name);
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, content);
  return p;
}

function importAndIndexSamples() {
  for (const f of fs.readdirSync(SAMPLES)) {
    const doc = documents.importDocument(path.join(SAMPLES, f));
    indexing.indexDocument(doc.id);
  }
}

beforeEach(() => {
  tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kb-test-'));
  dataDir = path.join(tmp, 'data');
  persistence = new PersistenceService(dataDir);
  documents = new DocumentService(persistence);
  indexing = new IndexingService(persistence, documents);
  qa = new QaService(persistence, indexing, documents);
});

afterEach(() => {
  fs.rmSync(tmp, { recursive: true, force: true });
});

describe('PersistenceService', () => {
  it('rejects paths that escape the data directory', () => {
    expect(() => persistence.readText('../outside.txt')).toThrow(/escapes/);
    expect(() => persistence.writeJson('../../x.json', {})).toThrow(/escapes/);
  });

  it('returns null for corrupt JSON instead of throwing', () => {
    fs.writeFileSync(path.join(dataDir, 'bad.json'), '{not json');
    expect(persistence.readJson('bad.json')).toBeNull();
  });

  it('writes JSON without leaving temp files behind', () => {
    persistence.writeJson('a/b.json', { ok: true });
    expect(persistence.readJson('a/b.json')).toEqual({ ok: true });
    expect(fs.readdirSync(path.join(dataDir, 'a'))).toEqual(['b.json']);
  });
});

describe('DocumentService', () => {
  it('imports a markdown file, using its heading as the title', () => {
    const doc = documents.importDocument(path.join(SAMPLES, 'design-notes.md'));
    expect(doc.title).toBe('Software Design Notes');
    expect(doc.status).toBe('imported');
    expect(documents.listDocuments()).toHaveLength(1);
    expect(documents.getDocumentContent(doc.id)).toContain('layered architecture');
  });

  it('keeps two files with the same name separate', () => {
    const a = documents.importDocument(writeFile('one/notes.txt', 'first file'));
    const b = documents.importDocument(writeFile('two/notes.txt', 'second file'));
    expect(documents.getDocumentContent(a.id)).toBe('first file');
    expect(documents.getDocumentContent(b.id)).toBe('second file');
    documents.deleteDocument(a.id);
    expect(documents.getDocumentContent(b.id)).toBe('second file');
  });

  it('rejects unsupported, binary, empty and missing files', () => {
    expect(() => documents.importDocument(writeFile('x.pdf', 'pdf'))).toThrow(/Unsupported/);
    expect(() => documents.importDocument(writeFile('bin.txt', Buffer.from([1, 0, 2])))).toThrow(/binary/);
    expect(() => documents.importDocument(writeFile('empty.txt', '  \n'))).toThrow(/empty/);
    expect(() => documents.importDocument(path.join(tmp, 'nope.txt'))).toThrow(/not found/);
    expect(documents.listDocuments()).toHaveLength(0);
  });

  it('normalises BOM and CRLF line endings', () => {
    const doc = documents.importDocument(writeFile('win.txt', '\uFEFFline one\r\nline two'));
    expect(documents.getDocumentContent(doc.id)).toBe('line one\nline two');
  });

  it('removes stored content when deleting', () => {
    const doc = documents.importDocument(writeFile('d.txt', 'some text'));
    expect(documents.deleteDocument(doc.id)).toBe(true);
    expect(documents.getDocumentContent(doc.id)).toBeNull();
    expect(fs.readdirSync(path.join(dataDir, 'documents'))).toEqual([]);
    expect(documents.deleteDocument(doc.id)).toBe(false);
  });

  it('ignores invalid ids rather than touching the filesystem', () => {
    expect(documents.getDocumentContent('../../etc/passwd')).toBeNull();
  });
});

describe('chunkText', () => {
  it('merges short paragraphs up to the chunk size', () => {
    const chunks = chunkText(['a'.repeat(200), 'b'.repeat(200), 'c'.repeat(200)].join('\n\n'), 500);
    expect(chunks).toHaveLength(2);
    expect(chunks[0]).toBe(`${'a'.repeat(200)}\n\n${'b'.repeat(200)}`);
  });

  it('splits oversized paragraphs at sentence boundaries', () => {
    const para = Array.from({ length: 40 }, (_, i) => `Sentence number ${i} is here.`).join(' ');
    const chunks = chunkText(para, 300);
    expect(chunks.length).toBeGreaterThan(2);
    for (const c of chunks) expect(c.length).toBeLessThanOrEqual(330);
    expect(chunks.join(' ').replace(/\s+/g, ' ')).toBe(para);
  });

  it('hard-splits text with no punctuation', () => {
    const chunks = chunkText('word '.repeat(1000), 500);
    for (const c of chunks) expect(c.length).toBeLessThanOrEqual(1000);
  });
});

describe('IndexingService', () => {
  it('indexing a single document makes it searchable and marks it indexed', () => {
    const doc = documents.importDocument(path.join(SAMPLES, 'meeting-summary.txt'));
    const n = indexing.indexDocument(doc.id);
    expect(n).toBeGreaterThan(0);
    expect(indexing.getAllChunks()).toHaveLength(n);
    expect(documents.getDocument(doc.id)).toMatchObject({ status: 'indexed', chunks: n });
  });

  it('re-indexing replaces chunks instead of duplicating them', () => {
    const doc = documents.importDocument(path.join(SAMPLES, 'meeting-summary.txt'));
    const n = indexing.indexDocument(doc.id);
    indexing.indexDocument(doc.id);
    expect(indexing.getAllChunks()).toHaveLength(n);
  });

  it('indexPending picks up unindexed and interrupted documents', () => {
    const a = documents.importDocument(writeFile('a.txt', 'alpha text'));
    const b = documents.importDocument(writeFile('b.txt', 'beta text'));
    documents.updateDocument(b.id, { status: 'indexing' });
    indexing.indexPending();
    expect(documents.getDocument(a.id)?.status).toBe('indexed');
    expect(documents.getDocument(b.id)?.status).toBe('indexed');
  });

  it('removeDocument drops chunks from the index', () => {
    const doc = documents.importDocument(writeFile('a.txt', 'alpha text'));
    indexing.indexDocument(doc.id);
    indexing.removeDocument(doc.id);
    expect(indexing.getAllChunks()).toHaveLength(0);
    expect(indexing.getChunksForDocument(doc.id)).toEqual([]);
  });
});

describe('retrieval', () => {
  it('stems common suffixes consistently', () => {
    expect(stem('chunks')).toBe('chunk');
    expect(stem('chunking')).toBe('chunk');
    expect(stem('indexes')).toBe('index');
    expect(stem('class')).toBe('class');
  });

  it('drops stop words', () => {
    expect(tokenize('What is the chunk size?')).toEqual(['chunk', 'size']);
  });

  it('ranks rare-term matches above common-term matches', () => {
    const mk = (id: string, content: string) => ({ id, documentId: id, content, index: 0, metadata: {} });
    const index = new Bm25Index([
      mk('1', 'document document document'),
      mk('2', 'document about electron preload bridge'),
      mk('3', 'document again'),
    ]);
    expect(index.search('electron document')[0].chunk.id).toBe('2');
  });
});

describe('QaService', () => {
  it('says so when nothing is indexed', async () => {
    const res = await qa.ask('What is the architecture?');
    expect(res.answer).toBe(NO_DOCUMENTS_ANSWER);
    expect(res.citations).toEqual([]);
  });

  it('answers from the documents with matching citations', async () => {
    importAndIndexSamples();
    const res = await qa.ask('What did the team decide about the vector database?');
    expect(res.engine).toBe('extractive');
    expect(res.answer).toMatch(/local chunk storage instead of a vector database/);
    expect(res.citations[0].documentTitle).toBe('meeting-summary');
    // Every marker in the answer resolves to a citation.
    for (const m of res.answer.matchAll(/\[(\d+)\]/g)) {
      expect(res.citations.some(c => c.marker === Number(m[1]))).toBe(true);
    }
    expect(res.confidence).toBeGreaterThan(0.5);
  });

  it('finds the right document for different questions', async () => {
    importAndIndexSamples();
    const preload = await qa.ask('What does the preload script do?');
    expect(preload.citations[0].documentTitle).toBe('Software Design Notes');
    expect(preload.answer).toMatch(/bridge/);

    const confidence = await qa.ask('How is the confidence score calculated?');
    expect(confidence.citations[0].documentTitle).toBe('Retrieval Plan');
    expect(confidence.answer).toMatch(/0\.85|0\.30/);
  });

  it('does not invent an answer for unrelated questions', async () => {
    importAndIndexSamples();
    const res = await qa.ask('What is the capital of Mongolia?');
    expect(res.answer).toBe(NOT_FOUND_ANSWER);
    expect(res.citations).toEqual([]);
    expect(res.confidence).toBe(0);
  });

  it('reflects deletions immediately', async () => {
    importAndIndexSamples();
    const meeting = documents.listDocuments().find(d => d.filename === 'meeting-summary.txt')!;
    indexing.removeDocument(meeting.id);
    documents.deleteDocument(meeting.id);
    const res = await qa.ask('What did the attendees discuss in the meeting?');
    expect(res.citations.every(c => c.documentId !== meeting.id)).toBe(true);
  });

  it('records history and can clear it', async () => {
    importAndIndexSamples();
    await qa.ask('What is the chunk size?');
    expect(qa.getHistory()).toHaveLength(1);
    qa.clearHistory();
    expect(qa.getHistory()).toEqual([]);
  });

  it('rejects empty questions', async () => {
    await expect(qa.ask('   ')).rejects.toThrow(/empty/);
  });
});

describe('splitSentences', () => {
  it('skips headings, strips list markers, and keeps decimals intact', () => {
    expect(splitSentences('## Heading\n- Version 1.2 is the current release. Next one soon.')).toEqual([
      'Version 1.2 is the current release.',
      'Next one soon.',
    ]);
  });
});

