 * A line ending in ":" followed by list items becomes one unit ("X includes: a; b; c.") so the
 * list isn't separated from the sentence that introduces it.
 */
export function splitSentences(text: string): string[] {
  const lines = text.split('\\n').map(l => l.trim());
  const out: string[] = [];
