    const candidates: Candidate[] = [];
    hits.forEach((hit, rank) => {
      splitUnits(hit.chunk.content).forEach((unit, pos) => {
        const own = new Set(tokenize(unit.text).filter(t => queryTerms.includes(t)));
        // Terms that only appear in the section heading count for half: they place the sentence in the right section.
        const fromHeading = new Set(tokenize(unit.context).filter(t => queryTerms.includes(t) && !own.has(t)));
        if (own.size === 0 && fromHeading.size === 0) return;
        const weight = weigh(own) + 0.5 * weigh(fromHeading);
        // Prefer sentences from higher-ranked chunks, and penalise very long ones slightly.
        const score = weight * (1 - rank * 0.05) * (unit.text.length > 400 ? 0.8 : 1);
        candidates.push({ text: unit.text, hit, rank, pos, score, terms: new Set([...own, ...fromHeading]) });
      });
    });

    candidates.sort((a, b) => b.score - a.score);
    const chosen: Candidate[] = [];
    const covered = new Set<string>();
    for (const c of candidates) {
      if (chosen.length >= MAX_ANSWER_SENTENCES) break;
      if (chosen.some(x => x.text === c.text)) continue;
      // After the first sentence, only add sentences that contribute something new or are nearly as strong.
      const addsNew = [...c.terms].some(t => !covered.has(t));
      if (chosen.length > 0 && !addsNew && c.score < chosen[0].score * 0.6) continue;
      chosen.push(c);
      c.terms.forEach(t => covered.add(t));
    }

    if (chosen.length === 0) {
      return { answer: NOT_FOUND_ANSWER, citations: [], confidence: 0, engine: 'extractive' };
    }

    const citations: Citation[] = [];
    const markerFor = (hit: ScoredChunk): number => {
      const existing = citations.find(c => c.documentId === hit.chunk.documentId && c.chunkIndex === hit.chunk.index);
      if (existing) return existing.marker;
      const citation = this.toCitation(hit, citations.length + 1);
      citations.push(citation);
      return citation.marker;
    };

    // Read in document order within each passage; one marker per run of sentences from the same passage.
    const best = chosen[0];
    chosen.sort((a, b) => (a.hit === best.hit ? -1 : 0) - (b.hit === best.hit ? -1 : 0) || a.rank - b.rank || a.pos - b.pos);
    const parts = chosen.map((c, i) => {
      const lastOfRun = chosen[i + 1]?.hit !== c.hit;
      return lastOfRun ? `${ensurePeriod(c.text)} [${markerFor(c.hit)}]` : ensurePeriod(c.text);
    });
    // Show the remaining strong passages as extra sources.
    for (const hit of hits) {
      if (citations.length >= MAX_CITATIONS) break;
      markerFor(hit);
    }

