  for (const para of paragraphs) {
    if (buffer.length > 0 && length + para.length + 2 > size) {
      // Don't strand a heading at the end of a chunk: carry it over to the section it introduces.
      const carried: string[] = [];
      while (buffer.length > 1 && isHeading(buffer[buffer.length - 1])) carried.unshift(buffer.pop()!);
