// Drives the built app: isolated userData, import samples, ask questions through the real UI, screenshot.
const { app, BrowserWindow } = require('electron');
const path = require('path');
const fs = require('fs');
const root = process.env.KB_ROOT;
const out = process.env.SMOKE_OUT;
app.setPath('userData', path.join(out, 'userdata'));
require(path.join(root, 'dist/main/main.js'));
const wait = ms => new Promise(r => setTimeout(r, ms));
const errors = [];
app.on('web-contents-created', (_e, wc) => wc.on('console-message', (_ev, level, msg) => { if (level >= 2) errors.push(msg); }));
app.whenReady().then(async () => {
  await wait(1500);
  const win = BrowserWindow.getAllWindows()[0];
  const js = code => win.webContents.executeJavaScript(code);
  const shot = async name => fs.writeFileSync(path.join(out, name), (await win.webContents.capturePage()).toPNG());
  try {
    await shot('1-empty.png');
    // Click "Load sample documents" in the empty state.
    await js(`[...document.querySelectorAll('button')].find(b => b.textContent.includes('Load sample')).click()`);
    await wait(1000);
    const docs = await js(`[...document.querySelectorAll('.doc-item .title')].map(e => e.textContent)`);
    console.log('DOCS', JSON.stringify(docs));
    const viewer = await js(`document.querySelector('.viewer-header h2')?.textContent`);
    console.log('VIEWER', viewer, '| passages:', await js(`document.querySelectorAll('.passage').length`));
    // Ask via the textarea + Enter.
    const ask = async q => {
      await js(`(() => { const t = document.querySelector('.qa-form textarea');
        const set = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
        set.call(t, ${JSON.stringify(q)}); t.dispatchEvent(new Event('input', { bubbles: true }));
        t.dispatchEvent(new KeyboardEvent('keydown', { key: 'Enter', bubbles: true })); })()`);
      await wait(800);
      return js(`(() => { const a = [...document.querySelectorAll('.answer')].pop(); return a && a.querySelector('.text').textContent; })()`);
    };
    console.log('ANSWER1', await ask('What did the team decide about the vector database?'));
    console.log('HIGHLIGHT', await js(`document.querySelector('.passage.highlight')?.textContent.slice(0, 80)`), '| viewer:', await js(`document.querySelector('.viewer-header h2')?.textContent`));
    console.log('ANSWER2', await ask('What does the preload script do?'));
    console.log('VIEWER2', await js(`document.querySelector('.viewer-header h2')?.textContent`));
    await shot('2-answered.png');
    // Click a source card for the first answer -> should switch the viewer.
    await js(`document.querySelector('.answer .source').click()`);
    await wait(500);
    console.log('AFTER-CITE-CLICK', await js(`document.querySelector('.viewer-header h2')?.textContent`));
    console.log('ANSWER3', await ask('What is the capital of Mongolia?'));
    // Delete flow: Delete -> Confirm delete.
    const before = await js(`document.querySelectorAll('.doc-item').length`);
    await js(`[...document.querySelectorAll('.viewer-header button')].find(b => b.textContent === 'Delete').click()`);
    await wait(200);
    await js(`[...document.querySelectorAll('.viewer-header button')].find(b => b.textContent === 'Confirm delete').click()`);
    await wait(600);
    console.log('DELETE', before, '->', await js(`document.querySelectorAll('.doc-item').length`));
    console.log('STATUS', await js(`document.querySelector('.statusbar').textContent`));
    await shot('3-final.png');
  } catch (e) {
    console.log('SMOKE ERROR', e);
  }
  console.log('RENDERER ERRORS', JSON.stringify(errors));
  app.exit(0);
});
EOF
